import{_ as e,o as s,c as i,a6 as n}from"./chunks/framework.BJFjZBwW.js";const t="/dev/assets/OpenMQTTGateway_Wifi_Manager_menu.B50OfVTl.png",o="/dev/assets/OpenMQTTGateway_Wifi_Manager_enter_parameters.C5xiZbGD.png",r="/dev/assets/OpenMQTTGateway_Wifi_Manager_save.D6TCOq5S.png",k=JSON.parse('{"title":"Wifi and MQTT configuration","description":"","frontmatter":{},"headers":[],"relativePath":"upload/portal.md","filePath":"upload/portal.md","lastUpdated":1762781769000}'),l={name:"upload/portal.md"};function p(c,a,h,d,u,m){return s(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="wifi-and-mqtt-configuration" tabindex="-1">Wifi and MQTT configuration <a class="header-anchor" href="#wifi-and-mqtt-configuration" aria-label="Permalink to &quot;Wifi and MQTT configuration&quot;">​</a></h1><h2 id="configuration-portal" tabindex="-1">Configuration portal <a class="header-anchor" href="#configuration-portal" aria-label="Permalink to &quot;Configuration portal&quot;">​</a></h2><p>Once loaded into your ESP, and if you don&#39;t use the manual configuration, you have to set your network parameters with WiFi Manager portal.</p><p>From your smartphone, search for  OpenMQTTGateway or OMG_ WiFi network and connect to it without password, or if you are using a device sold by Theengs or the macro <code>-DWM_PWD_FROM_MAC=true</code>, the password will be the last eight digits of the device MAC Address with upper case. Example, the password would be <code>CCDDEEFF</code> for a MAC Address <code>AABBCCDDEEFF</code>. For the Theengs Plug, the MAC Address can be found on the device sticker, and for all the devices, it is printed on the serial monitor logs.</p><p>Once connected to the WiFi, a web page should appear. On Android, you may also have a popup asking you if you want to connect to it without an internet connection. Answer yes always/all the time. If the web page doesn&#39;t appear, click on the WiFi Access Point and &quot;Manage router&quot;.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For boards with an ethernet port you can also access to the Wifi Manager portal through the LAN board IP address.</p></div><p><img src="'+t+'" alt="WiFi manager menu"></p><ul><li>Click on Configure WiFi</li></ul><p><img src="'+o+'" alt="WiFi manager parameters"></p><ul><li>Select your WiFi</li><li>Set your WiFi password</li></ul><p>::: note If the board is connected by ethernet, the Wifi and password can be empty. If you fill them the board will use this wifi as a fallback connectivity method. :::</p><ul><li>Set your MQTT Server IP or domain name (for Home Assistant you can enter <code>homeassistant.local</code> if your server is configured with mDNS)</li><li>Set your MQTT Server Port (default: 1883)</li><li>Set your MQTT Server username (optional, 64 characters maximum)</li><li>Set your MQTT Server password (optional, 64 characters maximum)</li><li>Set your MQTT base topic if you need to change it (you must keep the / at the end) (default: home/, 64 characters maximum)</li><li>Set your gateway name if you need to change it</li><li>Set your gateway password (default: empty, 8 characters minimum, 64 maximum), this password is used for <ul><li>Local and remote OTA</li><li>WebUI login (login:&quot;admin&quot;, password: &quot;&quot;)</li><li>WiFi Manager Access Point password after initial config</li></ul></li><li>Set the MQTT secure connection box to select whether or not the connection should be secure</li><li>Set the certificate validation to select wether or not you want to validate the server identity with a certificate</li><li>Copy/paste the MQTT server certificate in the MQTT server cert box (only required if using a secure connection), be sure to include the <code>-----BEGIN CERTIFICATE-----</code> and <code>-----END CERTIFICATE-----</code> markers</li><li>Add your certificates</li><li>Click on save</li></ul><p><img src="'+r+`" alt="WiFi manager save"></p><p>The ESP restart and connect to your network. Note that your credentials are saved into the ESP memory, if you want to redo the configuration you have to erase the ESP memory with the flash download tool.</p><p>Once done the gateway should connect to your network and your broker, you should see it into the broker in the form of the following messages:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>home/OpenMQTTGateway/LWT Online</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Note that the web portal appears only on first boot, if you want to configure again the setting you can do a long press on TRIGGER_GPIO, <a href="./../use/gateway.html#erase-the-esp-settings">erase the settings</a> or Reset the configuration from the WebUI.</p><h2 id="build-time-configuration" tabindex="-1">Build time configuration <a class="header-anchor" href="#build-time-configuration" aria-label="Permalink to &quot;Build time configuration&quot;">​</a></h2><p>You can configure your MQTT server credentials and network configuration before building the application. It can be done either in Arduino or in Platformio IDE thought the User_config.h file. Note that with Platformio IDE you can also set your credentials into the platformio.ini file or an *_env.ini file, here is an example with the Olimex ESP32 gateway:</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[env:esp32-olimex-gtw-ble]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">platform</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = \${com.esp32_platform}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">platform_packages</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = \${com.esp32_platform_packages}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">board</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = esp32-gateway</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">board_build.partitions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = min_spiffs.csv</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">lib_deps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  \${com-esp.lib_deps}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  \${libraries.ble}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">build_flags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  \${com-esp.build_flags}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DZgatewayBT=&quot;BT&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DLED_INFO=33&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DLED_INFO_ON=1&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DESP32_ETHERNET=true&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DMQTT_SERVER=&quot;11.22.33.44&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DMQTT_USER=&quot;salut&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DMQTT_PASS=&quot;atoi&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;-DGateway_Name=&quot;OpenMQTTGateway_ESP32_OLM_GTW&quot;&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div>`,20)])])}const b=e(l,[["render",p]]);export{k as __pageData,b as default};
